-- ============================================================================
-- LABOUR MONITORING ROUNDS - FIELD COMPLETENESS
-- INPUT: a table or CTE named `mahis_monitoring` (output of mahis_ld_monitoring.sql).
-- Generated by build_ld_round_dqa_scripts.py from the MNH Labour & Delivery data dictionary.
-- ============================================================================
WITH rounds AS (
    SELECT * FROM mahis_monitoring WHERE 1 = 1
),

rules AS (
    SELECT 'fetal_heart_rate' AS field, 'ld_mon_exam_heart' AS dictionary_name, 'Fetal heart rate' AS label
    UNION ALL
    SELECT 'cervical_dilation' AS field, 'ld_mon_exam_cervical' AS dictionary_name, 'Cervical dilation' AS label
    UNION ALL
    SELECT 'contractions' AS field, 'ld_mon_exam_contractions' AS dictionary_name, 'Contractions (checked every hour)' AS label
    UNION ALL
    SELECT 'amount_of_urine' AS field, 'ld_mon_exam_urine_volume' AS dictionary_name, 'Urine volume' AS label
    UNION ALL
    SELECT 'color_of_urine' AS field, 'ld_mon_exam_urine_color' AS dictionary_name, 'Urine color' AS label
    UNION ALL
    SELECT 'odour_of_urine' AS field, 'ld_mon_exam_urine_odour' AS dictionary_name, 'Urine odour' AS label
),

field_status AS (
    SELECT encounter_id, person_id, 'fetal_heart_rate' AS field, CASE WHEN fetal_heart_rate IS NOT NULL THEN 1 ELSE 0 END AS present FROM rounds
    UNION ALL
    SELECT encounter_id, person_id, 'cervical_dilation' AS field, CASE WHEN cervical_dilation IS NOT NULL THEN 1 ELSE 0 END AS present FROM rounds
    UNION ALL
    SELECT encounter_id, person_id, 'contractions' AS field, CASE WHEN contractions IS NOT NULL THEN 1 ELSE 0 END AS present FROM rounds
    UNION ALL
    SELECT encounter_id, person_id, 'amount_of_urine' AS field, CASE WHEN amount_of_urine IS NOT NULL THEN 1 ELSE 0 END AS present FROM rounds
    UNION ALL
    SELECT encounter_id, person_id, 'color_of_urine' AS field, CASE WHEN color_of_urine IS NOT NULL THEN 1 ELSE 0 END AS present FROM rounds
    UNION ALL
    SELECT encounter_id, person_id, 'odour_of_urine' AS field, CASE WHEN odour_of_urine IS NOT NULL THEN 1 ELSE 0 END AS present FROM rounds
)

SELECT
    r.field,
    r.dictionary_name,
    r.label,
    COUNT(*) AS rounds_required,
    SUM(f.present) AS rounds_present,
    COUNT(*) - SUM(f.present) AS rounds_missing,
    ROUND(100 * SUM(f.present) / COUNT(*), 1) AS pct_present,
    ROUND(100 * (COUNT(*) - SUM(f.present)) / COUNT(*), 1) AS pct_missing,
    CASE WHEN SUM(f.present) = COUNT(*) THEN 'COMPLETE' WHEN SUM(f.present) = 0 THEN 'ALL MISSING' ELSE 'PARTIAL' END AS status
FROM rules r
INNER JOIN field_status f ON f.field = r.field
GROUP BY r.field, r.dictionary_name, r.label
ORDER BY pct_present, r.field;
